def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    hot_dog_patches = image_patch.find("hot dog")
    goldfish_patches = image_patch.find("goldfish")

    if not hot_dog_patches or not goldfish_patches:
        return image_patch

    hot_dog_depths = [(hd, hd.compute_depth()) for hd in hot_dog_patches]
    goldfish_depths = [(gf, gf.compute_depth()) for gf in goldfish_patches]

    hot_dog_depths.sort(key=lambda x: x[1], reverse=True)
    goldfish_depths.sort(key=lambda x: x[1])

    for hd, hd_depth in hot_dog_depths:
        for gf, gf_depth in goldfish_depths:
            if is_behind(hd, gf):
                return hd

    return hot_dog_patches[0]

