def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    cows = image_patch.find("cow")
    couches = image_patch.find("couch")

    if not cows or not couches:
        return image_patch

    cow_couch_pairs = [(cow, couch) for cow in cows for couch in couches if distance(cow, couch) < 100]

    if not cow_couch_pairs:
        return image_patch

    best_pair = max(cow_couch_pairs, key=lambda pair: abs(pair[0].horizontal_center - pair[1].horizontal_center))

    cow, couch = best_pair

    if cow.horizontal_center < couch.horizontal_center:
        return cow
    else:
        return couch

